<script setup>
import {reactive,ref,onMounted,onUnmounted} from 'vue';import {api,messageOf} from '../api';import {auth} from '../auth';import {formatShanghai} from '../time';import {createLatestRequest} from '../latestRequest';import {runOperationOnce} from '../operationGuard';import ItemCard from '../components/ItemCard.vue'
const items=ref([]),interests=ref([]),handovers=ref([]),loading=ref(true),pending=reactive(new Set()),error=ref(''),notice=ref(''),mineRequests=createLatestRequest();const isPending=id=>pending.has(`handover:${id}`);async function load(){loading.value=true;error.value='';try{const result=await mineRequests.run(signal=>Promise.all([api.get('/items/mine',{signal}),api.get('/dashboard/mine',{signal})]));if(!result.accepted)return;const [a,b]=result.value;items.value=a.data.records;interests.value=b.data.interests;handovers.value=b.data.handovers;loading.value=false}catch(e){error.value=messageOf(e);loading.value=false}}async function action(handoverId,operation,msg){await runOperationOnce(pending,`handover:${handoverId}`,async()=>{error.value='';try{await api.post(`/handovers/${handoverId}/${operation}`);notice.value=msg;await load()}catch(e){error.value=messageOf(e)}})}const label=s=>({WAITING:'等待发布者确认',CONFIRMED:'已确认',CANCELLED:'已取消',ACTIVE:'待交接',COMPLETED:'已送出'}[s]||s);onMounted(load);onUnmounted(mineRequests.cancel)
</script>
<template><section><p class="eyebrow">我的空间</p><h1>我的</h1><p v-if="loading" class="state">加载中…</p><p v-else-if="error&& !items.length" class="state error">{{error}} <RouterLink v-if="error.includes('登录')" to="/login">去登录</RouterLink></p><template v-else><h2>我的发布</h2><div v-if="items.length" class="grid"><ItemCard v-for="item in items" :key="item.id" :item="item"/></div><p v-else class="state">还没有发布物品。</p><h2>我的想要</h2><div v-if="interests.length" class="stack"><div v-for="x in interests" :key="x.id" class="list-row"><div><RouterLink :to="`/items/${x.itemId}`"><strong>{{x.itemTitle}}</strong></RouterLink><p>{{label(x.status)}} · {{formatShanghai(x.startAt)}}</p></div></div></div><p v-else class="state">还没有表达过想要。</p><h2>我的交接卡</h2><div v-if="handovers.length" class="handover-grid"><article v-for="h in handovers" :key="h.id" class="handover-card"><span class="pill">{{label(h.status)}}</span><h3>{{h.itemTitle}}</h3><p>{{formatShanghai(h.startAt)}} 至 {{formatShanghai(h.endAt)}}</p><p>地点：{{h.location}}</p><p>发布者：{{h.publisherName}} · 领取人：{{h.recipientName}}</p><div v-if="h.status==='ACTIVE'"><button class="secondary" :disabled="isPending(h.id)" @click="action(h.id,'cancel','交接已取消，物品恢复可领取。')">{{isPending(h.id)?'处理中…':'取消交接'}}</button> <button v-if="auth.user?.id===h.publisherId" :disabled="isPending(h.id)" @click="action(h.id,'complete','交接已完成并归档。')">{{isPending(h.id)?'处理中…':'标记已送出'}}</button></div></article></div><p v-else class="state">暂无交接卡。</p><h2>已完成历史</h2><div class="stack"><RouterLink v-for="i in items.filter(x=>x.status==='COMPLETED')" :key="i.id" :to="`/items/${i.id}`">{{i.title}}</RouterLink><p v-if="!items.some(x=>x.status==='COMPLETED')" class="state">暂无已完成发布。</p></div></template><p v-if="notice" class="success">{{notice}}</p><p v-if="error" class="error">{{error}}</p></section></template>
